message.content:
{
  "1681": {
    "codebook_rule": ["1"],
    "document_id": "1681",
    "explanation": "The release says FEMA and OES 'have committed more than $5.6 million toward the repair of Humboldt County's Arcata and Jackson levees' and quotes Sen. Feinstein saying that with FEMA's approval of the grant, California can move forward with repairs. This attributes a concrete governmental benefit to the senator's efforts, so it is credit-claiming under Rule 1.",
    "label": "1"
  },
  "1938": {
    "codebook_rule": ["1"],
    "document_id": "1938",
    "explanation": "The release states that Sen. Dole 'announced' that HUD has approved a $12,662,958 Indian Housing Block Grant for the Lumbee Tribe. The release does not say that she secured the grant, requested it, or otherwise caused the award. It only announces the award and praises the tribe for securing the funding. This is not credit-claiming under Rule 1.",
    "label": "0"
  },
  "1967": {
    "codebook_rule": ["2"],
    "document_id": "1967",
    "explanation": "The release states that Sens. Lautenberg, Martinez, and Menendez 'introduced legislation to designate November National Homeless Youth Awareness Month.' This claims a leading legislative role in introducing a bill, which qualifies as credit-claiming under Rule 2.",
    "label": "1"
  },
  "2263": {
    "codebook_rule": [],
    "document_id": "2263",
    "explanation": "The release is a statement on the death of Pope John Paul II. It is a ceremonial statement and does not claim a role in a governmental outcome, funding award, or legislation. This is not credit-claiming.",
    "label": "0"
  },
  "2805": {
    "codebook_rule": [],
    "document_id": "2805",
    "explanation": "The release is a statement in response to EPA's mercury emissions rule. It criticizes the rule and notes that Sen. Feinstein co-sponsored the Clean Power Act. It does not claim a concrete governmental outcome or a leading legislative role that produced a result. This is not credit-claiming.",
    "label": "0"
  },
  "3168": {
    "codebook_rule": ["1", "2"],
    "document_id": "3168",
    "explanation": "The release states that Sen. Durbin 'helped secure 4 billion in emergency aid as part of the Supplemental Appropriations bill approved by the Senate Appropriations Committee today.' It also notes that he introduced a bill, S 2438, and sent a letter requesting inclusion of disaster assistance funds. This attributes a concrete governmental benefit to his efforts and claims a leading legislative role, so it is credit-claiming under Rules 1 and 2.",
    "label": "1"
  },
  "3728": {
    "codebook_rule": ["2"],
    "document_id": "3728",
    "explanation": "The release states that Sen. Conrad introduced a bill with 24 additional co-sponsors and that this was the third attempt by Sens. Conrad and Dorgan to get a vote on agriculture disaster assistance. It also notes that his first disaster assistance bill easily passed the Senate but was stripped out of a spending bill by House Republicans. This claims a leading legislative role in introducing and advancing legislation, so it is credit-claiming under Rule 2.",
    "label": "1"
  },
  "3880": {
    "codebook_rule": ["2"],
    "document_id": "3880",
    "explanation": "The release states that Sen. Johnson introduced The American Veterans Disabled for Life Commemorative Coin Act and that the bill would create a commemorative coin to help fund a memorial. It also notes that he worked to get committee approval of a separate measure he co-sponsored. This claims a leading legislative role in introducing and advancing legislation, so it is credit-claiming under Rule 2.",
    "label": "1"
  },
  "52": {
    "codebook_rule": ["2"],
    "document_id": "52",
    "explanation": "The release states that Sens. Kohl, Leahy, Grassley, Schumer, and Feingold will introduce the Preserve Access to Affordable Generics Act. It also notes that Sens. Grassley and Leahy were able to include their Drug Competition Act in the Medicare Modernization Act and that Sen. Schumer is the author of the Greater Access to Affordable Pharmaceuticals Act. This claims leading legislative roles in introducing and advancing legislation, so it is credit-claiming under Rule 2.",
    "label": "1"
  },
  "877": {
    "codebook_rule": ["1", "2"],
    "document_id": "877",
    "explanation": "The release states that Sen. Harkin, a senior member of the Senate Appropriations committee and its joint conference committee, announced that the committee has approved $1.75 million for transportation and economic development projects in Sioux City. It says the funding will be included in the conference report of the 2008 THUD Appropriations and will now seek final approval. It also notes that he is providing $536,000 for Harkin's Main Street project. This attributes a concrete governmental benefit to his efforts and claims a leading legislative role, so it is credit-claiming under Rules 1 and 2.",
    "label": "1"
  }
}

{
  "1020": {
    "codebook_rule": [],
    "document_id": "1020",
    "explanation": "Senator Feinstein's statement focuses on her reaction to an external commission's report regarding intelligence capabilities and weapons of mass destruction. She discusses recommendations and the general need for improved oversight. Although she mentions the Senate Intelligence Committee's investigation, she does not claim a leading role, authorship, or sponsorship of specific legislation or outcomes based on the text provided.",
    "label": "0"
  },
  "1869": {
    "codebook_rule": ["2"],
    "document_id": "1869",
    "explanation": "The press release explicitly states that Senator Burr 'introduced' legislation and identifies the bill (S. 3678). This fits rule 2, which includes claims of introducing, authoring, or sponsoring legislation.",
    "label": "1"
  },
  "198": {
    "codebook_rule": [],
    "document_id": "198",
    "explanation": "Senator Sununu announces a federal grant. However, the text does not state that he secured the funding, intervened in the application process, or was responsible for the outcome. Per rule 1's negative example, an announcement of a grant without a claimed role in obtaining it is not credit-claiming.",
    "label": "0"
  },
  "2156": {
    "codebook_rule": ["2"],
    "document_id": "2156",
    "explanation": "Senator Kennedy is described as having 'fought' for a comprehensive fix to immigration reform. The text refers to the 'McCain Kennedy bill' and mentions it was introduced by him last May. This indicates a leading legislative role and authorship/sponsorship of the bill.",
    "label": "1"
  },
  "3032": {
    "codebook_rule": ["2"],
    "document_id": "3032",
    "explanation": "The text states that Senator Cornyn 'has filed an amendment' to the Defense Authorization bill. Rule 2 includes claims of 'successfully adding a provision or amendment to legislation' or taking a leading role in such actions.",
    "label": "1"
  },
  "3093": {
    "codebook_rule": ["2"],
    "document_id": "3093",
    "explanation": "Senator Frist, as Majority Leader, expresses pride in the passage of a health package. While he doesn't claim authorship of every bill, the statement 'I am very proud to see completed' in the context of a 'succession of health related bills' passed under his leadership suggests he is claiming a role in advancing or securing passage of the package.",
    "label": "1"
  },
  "3233": {
    "codebook_rule": ["2"],
    "document_id": "3233",
    "explanation": "Senator Snowe (implied by 'I' and context) mentions she 'cosponsored' the Magnuson-Stevens Act reauthorization and 'worked closely' on the crafting of the bill. She also states that 'several provisions impacting Maine were included... at my request.' These are explicit claims of legislative leadership and provision inclusion.",
    "label": "1"
  },
  "3713": {
    "codebook_rule": [],
    "document_id": "3713",
    "explanation": "The release discusses a hearing on FDA drug safety. While Senator Enzi and Senator Kennedy are involved, the text focuses on their policy opinions, concerns, and the need for further study and legislation in the future. No concrete legislative action (like passing a bill) or specific funding outcome is attributed to their efforts yet.",
    "label": "0"
  },
  "673": {
    "codebook_rule": ["2"],
    "document_id": "673",
    "explanation": "Senator Bunning mentions he will be 're introducing my Coal To Liquids legislation.' This is a direct claim of legislative authorship and leadership in advancing a specific bill.",
    "label": "1"
  },
  "689": {
    "codebook_rule": ["1"],
    "document_id": "689",
    "explanation": "While the naming of the center is ceremonial, the text explicitly states that Senator Lugar 'helped the CHB secure loan guarantees through the U.S. Department of Agriculture.' This is a concrete claim of intervening to obtain a financial benefit/outcome for a constituent organization.",
    "label": "1"
  }
}

{
  "1806": {
    "codebook_rule": ["1"],
    "document_id": "1806",
    "explanation": "The document explicitly attributes the securing and preservation of the 9/11 responder funds to the efforts of the New York Congressional delegation, including Senators Clinton and Schumer. It states that the delegation 'fought hard to save' the money, that they 'secured the commitment' of the House Speaker to include the funding, and that Senator Clinton was 'grateful to my colleagues... who worked tirelessly to restore' the funds. These statements present the senators as instrumental in obtaining the concrete governmental benefit of federal medical funding.",
    "label": "1"
  },
  "2052": {
    "codebook_rule": [],
    "document_id": "2052",
    "explanation": "The text is a notification that a recording of a teleconference is available. It mentions that Senator Bunning held a conference call and commented on the Defense Authorization Bill and the Continuing Resolution, but it does not attribute any specific legislative outcome, funding, or benefit to his efforts or claim a leading legislative role. It is an announcement of an event without a claimed senatorial role.",
    "label": "0"
  },
  "2473": {
    "codebook_rule": [],
    "document_id": "2473",
    "explanation": "The release describes Senator Schumer's criticism of U.S. policy regarding the Armenian Genocide and his request for a nominee to clarify his position. The senator is expressing a policy opinion and asking a question of a nominee. There is no claim of a concrete governmental outcome or a legislative action attributed to his efforts.",
    "label": "0"
  },
  "2795": {
    "codebook_rule": ["1", "2"],
    "document_id": "2795",
    "explanation": "The headline and body state that Senators Murray and Cantwell have 'secured' $90 million for Pacific Salmon Recovery Efforts. The text explains that Murray secured the funding in the Senate Commerce, Justice and Science Appropriations bill. This satisfies Rule 1 by attributing a concrete funding outcome to their efforts. It also satisfies Rule 2 as the senators are credited with successfully adding or securing a provision (funding) within a bill that passed committee.",
    "label": "1"
  },
  "3391": {
    "codebook_rule": [],
    "document_id": "3391",
    "explanation": "Senator Domenici hosted a conference to gather information and discuss potential reforms for water resource management. While he acted as chairman of a committee, the text describes the event as a discussion and seeking input ('sought reforms', 'guide the committee'). It does not claim a specific legislative outcome, funding award, or program was achieved as a result of his efforts at this stage. It is an announcement of a conference and policy opinions.",
    "label": "0"
  },
  "3400": {
    "codebook_rule": [],
    "document_id": "3400",
    "explanation": "Senator Cardin denounces the President's decision to commute a prison sentence. This is a statement of policy opinion and criticism of another branch of government. It does not claim any legislative result or governmental benefit secured by the senator.",
    "label": "0"
  },
  "3522": {
    "codebook_rule": [],
    "document_id": "3522",
    "explanation": "The release describes a group of senators urging President Bush to help poorer nations deal with climate change and to secure an agreement at a conference. This is a request for executive action and a statement of policy opinion. As per the codebook definition, requests that have not produced an attributed result are not credit-claiming.",
    "label": "0"
  },
  "3552": {
    "codebook_rule": [],
    "document_id": "3552",
    "explanation": "Senator Leahy provides a statement on the modified Kyl-Cornyn amendment. He discusses the legislative process, acknowledges the work of other senators (Kyl, Cornyn, Reid, Durbin) in improving the text, and offers his own policy opinion on the amendment's content. He does not claim authorship, sponsorship, or leadership of the amendment himself; rather, he is commenting on it.",
    "label": "0"
  },
  "4608": {
    "codebook_rule": [],
    "document_id": "4608",
    "explanation": "Senators Dodd and Lieberman joined colleagues in sending a letter to the Secretary of HHS asking him to address financial constraints. This is a request for agency action ('asking the Secretary to address') and does not report a produced result or an outcome attributed to the senators' efforts. It falls under the definition of requests that have not produced an attributed result.",
    "label": "0"
  },
  "993": {
    "codebook_rule": ["1", "2"],
    "document_id": "993",
    "explanation": "The senators announce and praise final Congressional approval of a bill containing $19.1 million for a harbor deepening project. The release explicitly links the senators to the funding, with Isakson stating he is 'especially pleased that this bill includes' the funding. This implies a successful legislative role in securing the inclusion of the funds in the Appropriations bill, satisfying Rule 1 (attributing a concrete funding outcome) and Rule 2 (claiming a leading legislative role in securing a provision within passed legislation).",
    "label": "1"
  }
}

{
  "1292": {
    "codebook_rule": ["2"],
    "document_id": "1292",
    "explanation": "The release says Bond \"re-introduced his legislation\" to restore access to SBIR grants and notes that Talent joined as a cosponsor. This is a claim of legislative authorship/introduction and leadership in advancing legislation, which fits Rule 2. It is not merely an opinion or a request; it explicitly attributes the bill to the senator."
  ,
  "label": "1"
 },
 "1579": {
  "codebook_rule": ["1", "2"],
  "document_id": "1579",
  "explanation": "The release announces that Dodd's committee passed \"the Federal Housing Administration Modernization Act of 2007\" and describes it as part of \"Chairman Dodd's comprehensive strategy.\" It also states that Dodd \"successfully persuaded the Federal Reserve to meet its obligations\" and \"worked to secure $200 million in federal funding.\" These are claims of advancing legislation and obtaining/securing concrete outcomes, fitting both Rule 2 and Rule 1."
  ,
  "label": "1"
 },
 "1898": {
  "codebook_rule": [],
  "document_id": "1898",
  "explanation": "The senators announce support for Georgia's proposal to host a facility and say they \"will do everything we can to help\" and that their job is to ensure DHS understands Georgia's advantages. This is an announcement of support and future effort, not a claim that they secured, obtained, or advanced a concrete outcome. No result is attributed to their efforts."
  ,
  "label": "0"
 },
 "2780": {
  "codebook_rule": ["2"],
  "document_id": "2780",
  "explanation": "The release states that Harkin \"co sponsored The Family Smoking Prevention and Public Health Protection Act.\" The codebook's Rule 2 includes sponsorship as a leading legislative role. Even though the bill's final enactment is not claimed, the claim of sponsorship qualifies as credit-claiming. The rest is praise for a report and policy advocacy, but the sponsorship claim is sufficient."
  ,
  "label": "1"
 },
 "2974": {
  "codebook_rule": ["1"],
  "document_id": "2974",
  "explanation": "The release says Allard \"received a letter from Secretary of Defense Donald Rumsfeld containing assurances\" that Space Command would not be downgraded, and he said, \"I wanted an unmistakable commitment ... and I got it.\" This presents the senator as successfully intervening and obtaining a commitment from the Department of Defense, satisfying Rule 1. The rule covers obtaining agency action or concrete assurances/benefits attributable to the senator's efforts."
  ,
  "label": "1"
 },
 "2980": {
  "codebook_rule": [],
  "document_id": "2980",
  "explanation": "Harkin announces that the Region Six Planning Commission received $75,000 through the EDA and describes how the funds will be used. However, the text does not say he secured the funding, requested it, or otherwise caused the award. Under the Rule 1 negative example, announcing a concrete grant without claiming responsibility is not credit-claiming. No legislative authorship/sponsorship role is claimed either."
  ,
  "label": "0"
 },
 "3262": {
  "codebook_rule": [],
  "document_id": "3262",
  "explanation": "The senators and representative announce that ASU received a $26,590 HHS grant and praise its use. The release does not say the legislators secured, requested, or caused the grant. This matches the Rule 1 negative example: announcing a concrete grant without claiming senatorial responsibility is not credit-claiming. No legislative authorship/sponsorship role is claimed."
  ,
  "label": "0"
 },
 "340": {
  "codebook_rule": ["2"],
  "document_id": "340",
  "explanation": "Dodd announces that S. 763, the Public Transportation Terrorism Prevention Act, passed as part of 9/11 legislation. It says the transit security legislation was prompted by witnesses who testified before Dodd, that the Banking Committee approved the bill unanimously, and refers to \"Chairman Dodd's bill.\" These statements claim a leading legislative role in advancing and securing passage of the bill, fitting Rule 2. Even though final enactment may remain pending, Rule 2 explicitly includes such claims."
  ,
  "label": "1"
 },
 "450": {
  "codebook_rule": ["2"],
  "document_id": "450",
  "explanation": "Gregg comments on an FDA warning but states he \"has an amendment pending to the FDA reform bill\" requiring licensing of Internet pharmacies, and that the amendment is based on his \"Safe Internet Pharmacy Act of 2007\" he introduced earlier. Claiming authorship/introduction of legislation and a pending amendment is a claim of legislative leadership/authorship, satisfying Rule 2. The commentary and hope that the Senate approves the amendment are not alone credit-claiming, but the authorship claim is."
  ,
  "label": "1"
 },
 "799": {
  "codebook_rule": ["1", "2"],
  "document_id": "799",
  "explanation": "The release says Snowe and Collins \"announced more than $181,053,000 million in federal funding\" for projects benefiting Maine, says the funding was approved by the Appropriations Committee, and quotes them saying \"We will continue to work to secure funding.\" The announcement of a specific funding package for named Maine projects combined with the framing that they announced and will secure funding suggests attribution of the funding outcome to their efforts. It also implicates legislative appropriations work. The main Rule 1 negative example bars only cases where a grant is announced with no claim of securing/causing it; here the title and text say they \"secure\" funding and connect them to the appropriations outcome. Therefore it qualifies as credit-claiming under Rule 1 and likely Rule 2 as a legislative appropriations role. If strictly limited to explicit claims, the title's \"SECURE\" and the quote about securing funding are sufficient for Rule 1."
  ,
  "label": "1"
 }
}

{
  "1107": {
    "codebook_rule": [
      "2"
    ],
    "document_id": "1107",
    "explanation": "The release says Dodd sent letters requesting funding increases, which alone would be a request without an attributed result and therefore not credit-claiming. However, it also states that Dodd 'authored the Child Care and Development Block Grant' and has been an advocate for early childhood education. Claiming authorship of a program/legislation is a leading legislative role under Rule 2, so the document is classified as credit-claiming.",
    "label": "1"
  },
  "1696": {
    "codebook_rule": [],
    "document_id": "1696",
    "explanation": "Shelby announces transportation funding for Birmingham-area projects included in the FY2008 spending bill. The release describes the funding and projects but does not say Shelby secured, obtained, requested, authored, or otherwise caused the funding. Under Rule 1's negative example, announcing a concrete grant or funding without claiming responsibility is not credit-claiming.",
    "label": "0"
  },
  "2171": {
    "codebook_rule": [
      "2"
    ],
    "document_id": "2171",
    "explanation": "Allen 'enthusiastically co-sponsored' the Hunting Heritage Protection Act. Co-sponsorship is a claimed legislative role in advancing legislation, which falls under Rule 2's inclusion of sponsorship. Therefore this is credit-claiming.",
    "label": "1"
  },
  "2799": {
    "codebook_rule": [
      "1"
    ],
    "document_id": "2799",
    "explanation": "Cornyn's statement praises the President's disaster declaration but also says Sens. Cornyn and Hutchison 'urged President Bush after the flooding to expedite the federal major disaster declaration' and that Cornyn 'has been working with the El Paso community and the Texas congressional delegation to offer assistance at the federal level.' These statements connect Cornyn's efforts to the completed federal disaster declaration and recovery assistance, making this credit-claiming under Rule 1.",
    "label": "1"
  },
  "3838": {
    "codebook_rule": [],
    "document_id": "3838",
    "explanation": "The release describes Chambliss receiving an award from the Alliance for Worker Freedom based on his voting record. It is a ceremonial/honorific statement and does not claim that he secured a governmental benefit or authored/sponsored legislation. Mere recognition or voting record praise is not credit-claiming under the codebook.",
    "label": "0"
  },
  "3990": {
    "codebook_rule": [],
    "document_id": "3990",
    "explanation": "Menendez and Lautenberg sent a letter urging the Army Corps of Engineers to remove unexploded munitions by Memorial Day. This is a request/intervention that has not yet produced an attributed result. The codebook says requests without an attributed result are not credit-claiming.",
    "label": "0"
  },
  "4192": {
    "codebook_rule": [],
    "document_id": "4192",
    "explanation": "Mikulski explains her vote to confirm the FDA commissioner and expresses concerns and hopes. This is a statement explaining a vote and policy position, not a claim of securing an outcome or authorship/sponsorship/leadership in legislation. It is therefore not credit-claiming.",
    "label": "0"
  },
  "4251": {
    "codebook_rule": [
      "2"
    ],
    "document_id": "4251",
    "explanation": "Dole writes about Trade Adjustment Assistance and says she introduced a bill to improve the TAA program. Introducing legislation is a leading legislative role under Rule 2, even if final enactment is pending. Therefore this is credit-claiming.",
    "label": "1"
  },
  "633": {
    "codebook_rule": [
      "1"
    ],
    "document_id": "633",
    "explanation": "Baucus and Tester 'have recovered' more than $1.25 million in federal funding, 'requiring the senators to lobby agency official directly,' and Baucus says he is pleased they were able to 'secure these dollars.' The release attributes a concrete funding outcome to the senators' efforts, satisfying Rule 1.",
    "label": "1"
  },
  "838": {
    "codebook_rule": [
      "2"
    ],
    "document_id": "838",
    "explanation": "Most of the release criticizes President Bush's budget and is therefore not credit-claiming. However, it also says Corzine 'worked to thwart' a proposal to catalogue oil and gas reserves on the Outer Continental Shelf and that he 'introduced a permanent moratorium on drilling off the mid-Atlantic coast.' Introducing legislation is a leading legislative role under Rule 2, so the document is classified as credit-claiming.",
    "label": "1"
  }
}

{
  "1160": {
    "codebook_rule": ["1"],
    "document_id": "1160",
    "explanation": "Sen. Landrieu attributes the inclusion of $30 million for levee repairs in Terrebonne Parish to her own efforts. She explicitly states, 'my constant pushing and prodding of Chairmen Cochran and Domenici has paid off with the inclusion of this funding,' and notes her 'hard work and perseverance' has brought the project closer to reality. This constitutes credit-claiming under Rule 1, as she links a concrete funding outcome to her personal intervention and advocacy. Sen. Vitter's statement is not credit-claiming, as he only announces the funding and expresses hope for passage. Rep. Melancon's remarks do not claim a causal role. However, because the press release contains at least one credit-claiming statement by a senator (Landrieu), the text is classified as 1.",
    "label": "1"
  },
  "1231": {
    "codebook_rule": ["2"],
    "document_id": "1231",
    "explanation": "Sen. Domenici presents himself as instrumental in advancing the national energy policy bill. As Chairman of the Senate Energy and Natural Resources Committee, he states he is 'proud of this conference report' and 'proud of the process we used to draft this report,' indicating authorship and leadership in shaping the legislation. He highlights specific provisions he championed, such as conservation and efficiency measures, and claims credit for the bill's bipartisan and open process. This aligns with Rule 2, which includes claims of authorship, sponsorship, or leadership in advancing legislation, even if final enactment is pending.",
    "label": "1"
  },
  "2875": {
    "codebook_rule": ["1"],
    "document_id": "2875",
    "explanation": "Senators Snowe and Collins announce over $2.3 million in federal funding for health care and education projects in Maine and explicitly state that the bill 'includes funds, which we requested.' This language attributes the inclusion of the funding to their own efforts, satisfying Rule 1, which includes claims of securing funds or obtaining agency action. The release lists numerous specific earmarks and projects, reinforcing that the senators are presenting themselves as responsible for delivering concrete benefits to their state.",
    "label": "1"
  },
  "335": {
    "codebook_rule": ["2"],
    "document_id": "335",
    "explanation": "Sen. Rockefeller identifies himself as 'a co-author of the bipartisan, House-Senate, bill to reauthorize the Children's Health Insurance Program.' Although the House failed to override the veto, the codebook explicitly states that claims of authorship or sponsorship qualify as credit-claiming 'even if final enactment or implementation remains pending.' This satisfies Rule 2, as the senator claims a leading legislative role in crafting the bill. The rest of the statement focuses on criticism of the President and Congressional Republicans, which is not credit-claiming, but the co-authorship claim alone is sufficient.",
    "label": "1"
  },
  "3550": {
    "codebook_rule": [],
    "document_id": "3550",
    "explanation": "Sen. Dodd issues a statement on the death of Saddam Hussein, saying 'justice has been served' and calling for reconciliation in Iraq. This is a ceremonial or policy-opinion statement and does not attribute any governmental outcome, funding, program, or legislative action to the senator's own efforts. No rules apply.",
    "label": "0"
  },
  "4179": {
    "codebook_rule": ["2"],
    "document_id": "4179",
    "explanation": "Sen. Cornyn 'joined a bipartisan group of Senators... to introduce the Patent Reform Act of 2007.' This is a claim of sponsorship or co-sponsorship, which qualifies under Rule 2 as a leading legislative role, even though final enactment is pending. Cornyn also states he will 'work with Chairman Leahy and members on both sides of the aisle to reach a consensus,' further indicating active involvement in advancing the legislation.",
    "label": "1"
  },
  "4634": {
    "codebook_rule": [],
    "document_id": "4634",
    "explanation": "The Wyoming delegation, including Sens. Enzi and Barrasso and Rep. Cubin, sent a letter to the Forest Service requesting a public meeting and community input regarding a proposed office relocation. This is a request that has not produced an attributed result and does not claim a concrete outcome or legislative action. Per the codebook, 'requests that have not produced an attributed result are not credit-claiming.' No rules apply.",
    "label": "0"
  },
  "4651": {
    "codebook_rule": [],
    "document_id": "4651",
    "explanation": "Sen. Collins met with a youth volunteer award honoree to congratulate her and discuss her community service. This is a ceremonial statement recognizing a constituent and does not attribute any governmental benefit, policy, funding, or legislative action to the senator's efforts. No rules apply.",
    "label": "0"
  },
  "935": {
    "codebook_rule": ["1", "2"],
    "document_id": "935",
    "explanation": "Sen. Mikulski claims she 'created' the Community Innovations for Aging in Place program in the Older American Act Amendments of 2006, which satisfies Rule 2 (authorship/leadership in advancing legislation). Additionally, she 'received a promise' from Appropriations Subcommittee leaders to fight for funding for the program, and she states she 'will continue to fight to keep seniors across the country a priority in the federal checkbook.' The promise of funding, secured through her advocacy for a program she created, constitutes a concrete outcome attributed to her efforts, satisfying Rule 1.",
    "label": "1"
  },
  "981": {
    "codebook_rule": [],
    "document_id": "981",
    "explanation": "Sen. Whitehouse issues a statement on climate change following Al Gore's testimony. He mentions cosponsoring the Boxer-Sanders legislation to reduce emissions, but this is presented as part of a broader policy statement and does not claim authorship, sponsorship as a leading role, or a concrete outcome. The codebook distinguishes between 'voted in support' (not credit-claiming) and authorship/sponsorship (credit-claiming). Cosponsorship alone, without a claim of leadership or a resulting outcome, is ambiguous, but in this context, the release is primarily a policy opinion and criticism of inaction, not a claim of delivering a benefit or advancing legislation. Thus, no rules apply.",
    "label": "0"
  }
}

{
  "202": {
    "codebook_rule": [
      "2"
    ],
    "document_id": "202",
    "explanation": "The release states that Senators Domenici and Lieberman 'introduced the Biennial Budgeting and Appropriations Act of 2005' and describes Domenici as a longtime advocate and Lieberman as a co-sponsor. This claims a legislative authorship/sponsorship role, which falls under Rule 2.",
    "label": "1"
  },
  "2238": {
