    "label": "1"
  },
  "3857": {
    "codebook_rule": [],
    "document_id": "3857",
    "explanation": "The release is a tribute speech at a memorial service for Rosa Parks. It contains ceremonial and commemorative statements, with no claims of securing funding, policy outcomes, or legislative actions.",
    "label": "0"
  },
  "4356": {
