  },
  "2635": {
    "codebook_rule": [],
    "document_id": "2635",
    "explanation": "Senators Kerry and Kennedy announce that Andover schools will receive a federal grant, but the release does not attribute the funding to their efforts. This matches the negative example in rule 1 where announcing a grant without claiming responsibility is not credit-claiming.",
    "label": "0"
  },
  "2892": {
    "codebook_rule": ["1"],
    "document_id": "2892",
    "explanation": "The senator wrote to the President and Commerce Secretary urging reduction of tariffs on Mexican cement, and the resulting agreement is attributed to that intervention. This matches rule 1's definition of successfully intervening on behalf of constituents.",
