{
  "1276": {
    "codebook_rule": ["1"],
    "document_id": "1276",
    "explanation": "The senator announces more than $450,000 in federal grants awarded to Kansas fire departments and presents himself as pleased to announce these funds. The release attributes concrete funding awards to the announcement, but does not explicitly state that Senator Roberts secured, requested, or caused the grants. Under Rule 1, a concrete governmental outcome is announced but no senatorial role in obtaining it is claimed. Therefore, this is not credit-claiming.",
    "label": "0"
  },
  "2082": {
    "codebook_rule": ["2"],
    "document_id": "2082",
    "explanation": "Senator Feinstein urges passage of a bipartisan measure to increase fuel economy standards. The release mentions the bill is cosponsored by many senators and describes Feinstein's support, but does not state that she introduced, authored, sponsored, or successfully advanced the bill. Therefore, this is not credit-claiming under Rule 2.",
    "label": "0"
  },
  "2219": {
    "codebook_rule": ["1"],
    "document_id": "2219",
    "explanation": "Senator Gregg announces that the FY 2008 Omnibus Appropriations bill contains $195,000 for Elliot Health System. The release does not explicitly state that Gregg secured or obtained this funding. It describes the funding and its purpose, but attributes it to the appropriations bill generally. Therefore, this is not credit-claiming under Rule 1.",
    "label": "0"
  },
  "2956": {
    "codebook_rule": ["2"],
    "document_id": "2956",
    "explanation": "Senator Levin describes his role in modifying the Graham-Levin amendment and objecting to language that would strip court jurisdiction over pending cases. He states he worked with Senator Graham to modify the language, opposed certain provisions, and successfully prevented their inclusion in the final legislation. This is a claim of a leading legislative role in shaping and advancing legislation, satisfying Rule 2.",
    "label": "1"
  },
  "3068": {
    "codebook_rule": ["1"],
    "document_id": "3068",
    "explanation": "Senators Levin and Stabenow announce that nine Michigan organizations received over $450,000 through the Assistance to Firefighters Grant Program. The release does not state that the senators secured, requested, or caused the awards. It merely announces the funding. Therefore, this is not credit-claiming under Rule 1.",
    "label": "0"
  },
  "3138": {
    "codebook_rule": ["1"],
    "document_id": "3138",
    "explanation": "Senator Schumer announces that 25 Upstate New York counties have been designated as disaster areas by the USDA, qualifying farmers for emergency loans. The release does not state that Schumer secured, requested, or caused the designation. It announces the designation and describes its benefits. Therefore, this is not credit-claiming under Rule 1.",
    "label": "0"
  },
  "3243": {
    "codebook_rule": ["2"],
    "document_id": "3243",
    "explanation": "Senator Landrieu is described as having added a key provision to the Small Business Lending Reauthorization and Improvements Act. The release states she introduced a related bill, S. 738, and that her provision was included in the committee-approved bill. This is a claim of a leading legislative role, satisfying Rule 2.",
    "label": "1"
  },
  "3265": {
    "codebook_rule": ["2"],
    "document_id": "3265",
    "explanation": "Senator Bayh cosponsors the Dodd-Shelby Currency Manipulation Bill and urges further action. He also states he introduced the Fair Currency Act of 2007 with other senators. This is a claim of authorship or sponsorship of legislation, satisfying Rule 2.",
    "label": "1"
  },
  "449": {
    "codebook_rule": ["1"],
    "document_id": "449",
    "explanation": "Senator Cantwell presents a Purple Heart Medal to a veteran's family. This is a ceremonial statement honoring service and does not claim a governmental outcome, funding, or legislative action attributable to her efforts. Therefore, this is not credit-claiming under Rule 1.",
    "label": "0"
  },
  "837": {
    "codebook_rule": ["1"],
    "document_id": "837",
    "explanation": "Senators Lott and Cochran announce over $18 million in federal funding for Katrina recovery. The release states the funding is approved and describes the grants, but does not state that the senators secured, requested, or caused the funding. Therefore, this is not credit-claiming under Rule 1.",
    "label": "0"
  }
}

{
    "122": {
        "codebook_rule": [],
        "document_id": "122",
        "explanation": "The text describes Senator Conrad questioning a nominee, calling for hearings, urging agencies to reconsider or delay trade rules, and criticizing administration handling of mad cow disease. It contains requests, oversight, and policy positions, but no claim that he secured, delivered, authored, sponsored, or was responsible for a concrete governmental outcome or legislative action. Therefore, it is not credit-claiming.",
        "label": "0"
    },
    "1329": {
        "codebook_rule": [],
        "document_id": "1329",
        "explanation": "The delegation praises the BRAC Commission's decision to shift personnel to Dover Air Force Base and says the delegation stands ready to help implement changes. It does not attribute the decision to the senators' efforts, nor does it claim authorship, sponsorship, or leadership in obtaining the outcome. Thus, no credit-claiming.",
        "label": "0"
    },
    "1694": {
        "codebook_rule": [
            "2"
        ],
        "document_id": "1694",
        "explanation": "The release says Senator Clinton hailed final passage of the College Cost Reduction and Access Act and specifically states that the bill includes two provisions offered by Senator Clinton. It also says she is the sponsor of other related bills. Claiming offered provisions and sponsorship is a leading legislative role under Rule 2, so this is credit-claiming.",
        "label": "1"
    },
    "1907": {
        "codebook_rule": [],
        "document_id": "1907",
        "explanation": "Senator Schumer announces that he is working on and will introduce legislation to create grants for disaster-affected small businesses, and he calls on the President to issue a disaster declaration. These are announcements of intended legislation and requests without an attributed result. Under the codebook, requests that have not produced an attributed result and announcements without a claimed senatorial role are not credit-claiming.",
        "label": "0"
    },
    "2376": {
        "codebook_rule": [],
        "document_id": "2376",
        "explanation": "The text describes Senator Lugar hosting a Senate Thursday Club luncheon featuring Indiana food and gifts. This is a ceremonial or social event, not a governmental benefit, funding outcome, policy, program, or legislative action attributed to his efforts. Therefore, no credit-claiming.",
        "label": "0"
    },
    "2701": {
        "codebook_rule": [
            "2"
        ],
        "document_id": "2701",
        "explanation": "The release states that Senator Casey is a cosponsor of the Sudan Divestment Act and that he chaired a portion of a Banking Committee hearing on the Act. Cosponsorship and chairing a committee hearing are claims of sponsorship or leadership in advancing legislation under Rule 2. The committee's unanimous approval is also presented in connection with Casey's role, so this is credit-claiming.",
        "label": "1"
    },
    "34": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "34",
        "explanation": "The release says a federal NEA grant is being announced by Senator Crapo and that 'Crapo is working with the dance company on an additional grant.' The explicit statement that Crapo is working with the company on an additional grant attributes active advancement of a governmental funding benefit to his efforts. Although the awarded grant itself is only announced, the working-on-an-additional-grant language is a claimed role in pursuing federal funding, satisfying Rule 1. Ambiguity: if the phrase were read only as a future effort without result, it might not qualify, but the release ties the senator to the grant announcement and active work on federal grant support, so I classified it as credit-claiming.",
        "label": "1"
    },
    "383": {
        "codebook_rule": [
            "2"
        ],
        "document_id": "383",
        "explanation": "The text states that Senators Obama and Durbin reintroduced the STOP FRAUD Act. Introducing or reintroducing legislation is a leading legislative role under Rule 2, even if final enactment is pending. Therefore, this is credit-claiming.",
        "label": "1"
    },
    "4335": {
        "codebook_rule": [],
        "document_id": "4335",
        "explanation": "Senator Lieberman expresses disappointment that the Senate defeated a resolution rejecting an EPA mercury rule. The text notes he co-sponsored the resolution, but the main claim is a statement on a failed vote and criticism of EPA and the Senate outcome. It does not present him as responsible for, instrumental in obtaining, or successfully advancing a governmental benefit or legislative action. Because the co-sponsorship mention is incidental and the release focuses on a defeated measure rather than claimed advancement, I classified it as not credit-claiming. Ambiguity: Rule 2 includes sponsorship, but the negative example and definition emphasize successful or active advancement; here the outcome is defeat and the statement is primarily criticism.",
        "label": "0"
    },
    "4501": {
        "codebook_rule": [
            "1"
        ],
        "document_id": "4501",
        "explanation": "The release states that Senator Conrad 'has been instrumental in developing several projects to commemorate the Lewis and Clark bicentennial including the Lewis Clark Legacy Trails.' This directly claims that he was instrumental in developing commemorative projects, which are governmental or publicly beneficial projects. Under Rule 1, attributing a program/project/benefit to the senator's efforts is credit-claiming. The event itself is ceremonial, but the instrumental-development claim is separate and qualifies.",
        "label": "1"
    }
}

{
  "1237": {
    "codebook_rule": ["1"],
    "document_id": "1237",
    "explanation": "The release describes a federal funding award from the U.S. Department of Justice’s Justice and Mental Health Collaboration Program to Story County. Under Rule 1, the senator is credited with securing this governmental benefit. No other rules apply.",
