  },
  "4490": {
    "codebook_rule": ["2"],
    "document_id": "4490",
    "explanation": "The senator announces passage of his Senate resolution celebrating Black History Month. Rule 2 applies because he claims authorship and legislative passage of the resolution. Rule 1 does not apply because this is a ceremonial resolution rather than a concrete governmental benefit, funding award, program, or agency action.",
